from pathlib import Path
import json

import chromadb
from sentence_transformers import SentenceTransformer


PROJECT_ROOT = Path(__file__).resolve().parent.parent

CHUNKS_FILE = PROJECT_ROOT / "data" / "processed" / "chunks.json"
DATABASE_DIR = PROJECT_ROOT / "chroma_db"

COLLECTION_NAME = "forgeiq_knowledge"

EMBEDDING_MODEL_NAME = "sentence-transformers/all-MiniLM-L6-v2"


def load_chunks():
    """Load the chunks generated by the ingestion pipeline."""

    if not CHUNKS_FILE.exists():
        raise FileNotFoundError(
            f"Chunks file not found: {CHUNKS_FILE}. Run ingest.py first."
        )

    with CHUNKS_FILE.open("r", encoding="utf-8") as file:
        chunks = json.load(file)

    if not chunks:
        raise ValueError("The chunks file is empty.")

    return chunks


def create_vector_store(chunks):
    """
    Build the ChromaDB collection from chunks.

    This function rebuilds the collection each time it is called.
    We will separate indexing from searching in the next step.
    """

    model = SentenceTransformer(EMBEDDING_MODEL_NAME)

    client = chromadb.PersistentClient(path=str(DATABASE_DIR))

    existing_collections = client.list_collections()

    existing_names = [
        collection.name if hasattr(collection, "name") else collection
        for collection in existing_collections
    ]

    if COLLECTION_NAME in existing_names:
        client.delete_collection(name=COLLECTION_NAME)

    collection = client.create_collection(
        name=COLLECTION_NAME,
        metadata={"hnsw:space": "cosine"},
    )

    texts = [chunk["text"] for chunk in chunks]

    embeddings = model.encode(
        texts,
        normalize_embeddings=True,
        show_progress_bar=True,
    )

    metadata_fields = [
        "source",
        "document_id",
        "document_type",
        "revision",
        "status",
        "chunk_index",
        "section",
    ]

    metadatas = []

    for chunk in chunks:
        metadata = {}

        for field in metadata_fields:
            value = chunk.get(field)

            # ChromaDB metadata values must be supported scalar types.
            if value is None:
                continue

            if isinstance(value, (str, int, float, bool)):
                metadata[field] = value
            else:
                metadata[field] = str(value)

        metadatas.append(metadata)

    collection.upsert(
        ids=[chunk["chunk_id"] for chunk in chunks],
        documents=texts,
        embeddings=embeddings.tolist(),
        metadatas=metadatas,
    )

    return model, collection


def load_vector_store():
    """Load an existing ChromaDB collection without rebuilding it."""

    if not DATABASE_DIR.exists():
        raise FileNotFoundError(
            "The vector database does not exist yet. "
            "Run the indexing process first."
        )

    client = chromadb.PersistentClient(path=str(DATABASE_DIR))

    try:
        collection = client.get_collection(name=COLLECTION_NAME)
    except Exception as error:
        raise RuntimeError(
            "The ForgeIQ collection was not found. "
            "Build the vector database first."
        ) from error

    model = SentenceTransformer(EMBEDDING_MODEL_NAME)

    return model, collection


def search_knowledge_base(query, model, collection, top_k=3):
    """Retrieve the most semantically similar chunks."""

    if not query.strip():
        raise ValueError("Search query cannot be empty.")

    if top_k < 1:
        raise ValueError("top_k must be at least 1.")

    number_of_chunks = collection.count()

    if number_of_chunks == 0:
        return []

    query_embedding = model.encode(
        [query],
        normalize_embeddings=True,
    )

    results = collection.query(
        query_embeddings=query_embedding.tolist(),
        n_results=min(top_k, number_of_chunks),
        include=["documents", "metadatas", "distances"],
    )

    matches = []

    for index, document in enumerate(results["documents"][0]):
        metadata = results["metadatas"][0][index]

        matches.append({
            "text": document,
            "source": metadata.get("source", "Unknown"),
            "document_id": metadata.get("document_id", "Unknown"),
            "document_type": metadata.get(
                "document_type", "general_document"
            ),
            "revision": metadata.get("revision", "Unknown"),
            "status": metadata.get("status", "Unspecified"),
            "chunk_index": metadata.get("chunk_index", -1),
            "section": metadata.get("section", "Unknown"),
            "distance": results["distances"][0][index],
        })

    return matches


def main():
    chunks = load_chunks()

    print(f"Loaded {len(chunks)} chunks from the processed documents.")

    model, collection = create_vector_store(chunks)

    print(f"Vector database contains {collection.count()} chunks.")
    print("\nForgeIQ Semantic Search")
    print("Type 'exit' to quit.\n")

    while True:
        query = input("Ask a question: ").strip()

        if query.lower() in {"exit", "quit"}:
            break

        if not query:
            print("Please enter a question.\n")
            continue

        results = search_knowledge_base(
            query,
            model,
            collection,
            top_k=3,
        )

        print("\nRetrieved results:\n")

        for rank, result in enumerate(results, start=1):
            print(f"Result {rank}")
            print(f"Source: {result['source']}")
            print(f"Document ID: {result['document_id']}")
            print(f"Document type: {result['document_type']}")
            print(f"Revision: {result['revision']}")
            print(f"Status: {result['status']}")
            print(f"Section: {result['section']}")
            print(f"Chunk: {result['chunk_index']}")
            print(f"Cosine distance: {result['distance']:.4f}")
            print(f"Text: {result['text']}")
            print("-" * 60)

        print()


if __name__ == "__main__":
    main()

